@icontract.snapshot(lambda self: dict(self.environ), name="ENV")
@icontract.ensure(lambda result: isinstance(result, list))
@icontract.ensure(lambda result: all(isinstance(ip, str) for ip in result))
@icontract.ensure(lambda result, OLD: (
    [ip.strip() for ip in OLD.ENV['HTTP_X_FORWARDED_FOR'].split(',')]
    if ('HTTP_X_FORWARDED_FOR' in OLD.ENV and OLD.ENV.get('HTTP_X_FORWARDED_FOR'))
    else ([OLD.ENV['REMOTE_ADDR']] if ('REMOTE_ADDR' in OLD.ENV and OLD.ENV.get('REMOTE_ADDR')) else [])
) == result)
@icontract.ensure(lambda result, OLD: not any(ip in ('unknown', 'invalid_ip', '0.0.0.0') for ip in result))
